document.querySelectorAll('.e-con').forEach(e=>e.classList.add('e-lazyloaded'));
document.querySelectorAll('.eael-tabs-content > div').forEach((e,i)=>{e.style.display=i===0?'block':'none';e.classList.toggle('active',i===0);});
document.querySelectorAll('.eael-tabs-nav li[aria-selected="true"]').forEach(e=>e.classList.add('active'));
document.querySelectorAll('.eael-tabs-content .elementor-tab-title').forEach(e=>{e.setAttribute('aria-expanded','true');e.classList.add('elementor-active');if(e.nextElementSibling)e.nextElementSibling.style.display='block';});
document.querySelectorAll('.eael-accordion-header').forEach(e=>{e.setAttribute('role','button');e.setAttribute('aria-expanded','false');});
const panel=document.querySelector('#sapago-panel'),launcher=document.querySelector('#chat-launcher'),hint=document.querySelector('#sapago-hint'),input=document.querySelector('#chat-input'),messages=document.querySelector('#chat-messages');
let live=false,lastFocus;
function openChat(){if(live){const frame=document.querySelector('iframe[title="Sapago Live Chat"]');if(frame)frame.focus();return;}lastFocus=document.activeElement;panel.hidden=false;hint.hidden=true;launcher.setAttribute('aria-expanded','true');input.focus();}
function closeChat(){panel.hidden=true;launcher.setAttribute('aria-expanded','false');(lastFocus||launcher).focus();}
launcher.addEventListener('click',()=>panel.hidden?openChat():closeChat());
document.querySelector('#hint-open').addEventListener('click',openChat);
document.querySelector('#hint-close').addEventListener('click',()=>hint.hidden=true);
document.querySelector('#chat-close').addEventListener('click',closeChat);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)closeChat();});
document.querySelectorAll('a').forEach(a=>{if(a.dataset.chat||a.getAttribute('href')==='#form')a.addEventListener('click',e=>{e.preventDefault();openChat();});});
function bubble(text,role){const b=document.createElement('div');b.className='bubble '+role;b.textContent=text;messages.append(b);messages.scrollTop=messages.scrollHeight;}
function answer(text){const q=text.toLowerCase();
 if(/promo|diskon|potongan|pertama/.test(q))return 'Di website KitaLabel ada penawaran potongan Rp300.000 untuk order pertama. 🎉\n\nSyarat dan ketersediaan promo perlu dikonfirmasi ke tim KitaLabel. Produk apa yang ingin kamu beri label?';
 if(/varian|desain|design/.test(q))return 'KitaLabel dapat mendukung hingga 5 varian desain dalam satu kali cetak, sehingga kamu bisa mencetak beberapa varian produk sekaligus.\n\nBerapa varian yang kamu punya, dan digunakan untuk produk apa?';
 if(/material|bahan|film|transpar|silver|white|tahan|air/.test(q))return 'Ada tiga pilihan material di halaman ini:\n\n• Film White: tampilan putih bersih agar informasi produk terlihat jelas.\n• Film Silver: pilihan dengan tampilan silver.\n• Film Transparan: pilihan label dengan tampilan transparan.\n\nSebutkan jenis produk dan kemasannya agar tim dapat memberi rekomendasi material yang sesuai.';
 if(/harga|biaya|berapa|minimum|moq|jumlah/.test(q))return 'Harga dan minimum order perlu dikonfirmasi sesuai ukuran, material, jumlah label, dan varian desain.\n\nKamu bisa mulai dengan menyebutkan produk, ukuran label, dan jumlah yang dibutuhkan. Demo ini belum menghitung penawaran harga.';
 if(/lama|hari|waktu|kirim/.test(q))return 'Waktu produksi dan pengiriman perlu dikonfirmasi langsung ke tim KitaLabel berdasarkan spesifikasi dan jadwal pesanan.\n\nKapan labelnya dibutuhkan?';
 if(/alamat|lokasi|email|kontak|admin/.test(q))return 'Kontak KitaLabel yang tercantum di website:\n\n📍 Jl. Kapuk Blok F20-16E Delta, Lippo Cikarang\n✉️ info@kitalabel.com\n\nChat ini masih simulasi dan belum terhubung ke admin.';
 return 'Terima kasih! Untuk kebutuhan “'+text+'”, mulai dengan menyiapkan jenis kemasan, ukuran label, jumlah cetak, dan varian desain.\n\nSaya bisa menjelaskan pilihan material, cetak hingga 5 varian, atau promo order pertama. Balasan ini adalah simulasi demo SapaGo.';
}
function send(text){if(!text.trim())return;bubble(text.trim(),'user');input.value='';bubble(answer(text.trim()),'assistant');}
document.querySelector('#chat-form').addEventListener('submit',e=>{e.preventDefault();send(input.value);});
document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>send(b.dataset.question)));
// Native, dependency-free replacements for the original Elementor interactions.
document.querySelectorAll('.eael-advance-tabs').forEach(tabs=>{const triggers=[...tabs.querySelectorAll('.eael-tabs-nav li')],contents=[...tabs.querySelectorAll('.eael-tabs-content > div')];triggers.forEach((t,i)=>{t.tabIndex=0;function select(){triggers.forEach((x,j)=>{x.classList.toggle('active',i===j);x.setAttribute('aria-selected',String(i===j));});contents.forEach((x,j)=>{x.classList.toggle('active',i===j);x.style.display=i===j?'block':'none';});}t.addEventListener('click',select);t.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}});});});
document.querySelectorAll('.eael-accordion-header,.elementor-tab-title').forEach(h=>{h.tabIndex=0;const toggle=()=>{const c=h.nextElementSibling;if(!c)return;const expanded=h.getAttribute('aria-expanded')==='true';h.setAttribute('aria-expanded',String(!expanded));h.classList.toggle('active',!expanded);h.classList.toggle('elementor-active',!expanded);c.style.display=expanded?'none':'block';};h.addEventListener('click',toggle);h.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();toggle();}});});
document.querySelectorAll('.elementor-counter-number').forEach(n=>{n.textContent=n.dataset.toValue||n.textContent;});
document.querySelectorAll('.swiper,.swiper-container').forEach(carousel=>{const w=carousel.querySelector('.swiper-wrapper');if(!w)return;const slides=[...w.children].filter(s=>!s.classList.contains('swiper-slide-duplicate'));let index=0;function show(i){index=(i+slides.length)%slides.length;w.scrollTo({left:slides[index].offsetLeft-w.offsetLeft,behavior:'smooth'});}carousel.parentElement.querySelectorAll('.elementor-swiper-button-next,.swiper-button-next').forEach(b=>{b.setAttribute('aria-label','Gambar berikutnya');b.tabIndex=0;b.addEventListener('click',()=>show(index+1));b.addEventListener('keydown',e=>{if(e.key==='Enter')show(index+1);});});carousel.parentElement.querySelectorAll('.elementor-swiper-button-prev,.swiper-button-prev').forEach(b=>{b.setAttribute('aria-label','Gambar sebelumnya');b.tabIndex=0;b.addEventListener('click',()=>show(index-1));b.addEventListener('keydown',e=>{if(e.key==='Enter')show(index-1);});});});
const config=window.KITALABEL_SAPAGO;
if(config?.publicKey?.startsWith('lc_pk_')){const s=document.createElement('script');s.src=config.scriptUrl;s.dataset.apiKey=config.publicKey;s.dataset.apiUrl=config.apiUrl;s.dataset.widgetUrl=config.widgetUrl;s.onload=()=>{const watch=new MutationObserver(()=>{if(document.querySelector('iframe[title="Sapago Live Chat"]')){live=true;launcher.hidden=true;launcher.style.display='none';hint.hidden=true;panel.hidden=true;watch.disconnect();}});watch.observe(document.body,{childList:true,subtree:true});};document.body.append(s);}
